package cli

import (
	"context"
	"errors"
	"fmt"
	"github.com/gofrs/flock"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"k8s.io/client-go/tools/clientcmd"
)

// scrubLegacySessionConfigs is narrowly scoped to files generated by earlier
// devctl versions in this private profile. It never reads ~/.kube or arbitrary
// kubeconfigs. Replacing the old local delivery copy does not revoke backups or
// original credentials, which remain encrypted in the backend registry.
func scrubLegacySessionConfigs(dir string) error {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	lock := flock.New(filepath.Join(dir, "selection.lock"))
	ok, e := lock.TryLockContext(ctx, 50*time.Millisecond)
	if e != nil {
		return e
	}
	if !ok {
		return errors.New("cannot lock legacy session migration")
	}
	defer lock.Unlock()
	legacyBinding := filepath.Join(dir, "auto-binding.json")
	if info, err := os.Lstat(legacyBinding); err == nil {
		if !info.Mode().IsRegular() || info.Size() > 64<<10 || info.Mode().Perm()&0077 != 0 {
			return errors.New("legacy automatic binding must be a private regular file; remove it manually")
		}
		if err = os.Remove(legacyBinding); err != nil {
			return err
		}
	} else if !os.IsNotExist(err) {
		return err
	}
	entries, e := os.ReadDir(dir)
	if e != nil {
		return e
	}
	for _, entry := range entries {
		name := entry.Name()
		if name != "active-kubeconfig" && (!strings.HasSuffix(name, ".yaml") || !sessionID.MatchString(strings.TrimSuffix(name, ".yaml"))) {
			continue
		}
		path := filepath.Join(dir, name)
		original, e := os.Lstat(path)
		if e != nil {
			return e
		}
		if !original.Mode().IsRegular() {
			return fmt.Errorf("refusing non-regular app-owned session configuration %s", name)
		}
		if original.Size() > 2<<20 {
			return fmt.Errorf("app-owned session configuration %s is too large; remove the old local copy manually", name)
		}
		file, e := os.Open(path)
		if e != nil {
			return e
		}
		opened, e := file.Stat()
		if e != nil {
			file.Close()
			return e
		}
		// Reject replacement by a symlink before reading any contents, including
		// platforms without an O_NOFOLLOW flag in Go's portable os API.
		current, e := os.Lstat(path)
		if e != nil || !current.Mode().IsRegular() || !os.SameFile(original, opened) || !os.SameFile(current, opened) {
			file.Close()
			return errors.New("app-owned session configuration changed during migration")
		}
		raw, e := io.ReadAll(io.LimitReader(file, (2<<20)+1))
		file.Close()
		if e != nil {
			return e
		}
		if len(raw) > 2<<20 {
			return errors.New("app-owned session configuration exceeds migration limit")
		}
		config, e := clientcmd.Load(raw)
		if e != nil {
			return fmt.Errorf("cannot parse app-owned session configuration %s; remove the old local copy manually", name)
		}
		secret := false
		for _, user := range config.AuthInfos {
			if user == nil {
				continue
			}
			if user.Token != "" || user.TokenFile != "" || len(user.ClientKeyData) > 0 || user.ClientKey != "" || user.Password != "" || user.AuthProvider != nil {
				secret = true
			}
		}
		retired := false
		for _, cluster := range config.Clusters {
			if cluster != nil && (strings.Contains(cluster.Server, "/k8s/sessions/") || strings.Contains(cluster.Server, "/k8s/auto/")) {
				retired = true
			}
		}
		if secret || retired {
			if e = atomicPrivate(path, inactiveConfig); e != nil {
				return errors.New("cannot replace legacy app-owned credential configuration")
			}
		}
	}
	return nil
}
